public sealed record TemplateSave(string Name,string Subject,string Body,Guid? Version);
public static partial class WorkflowModule
{
 private static async Task ConfigureSchedule(WorkflowDefinition definition,WorkflowVersion version,WorkflowDbContext db,CancellationToken ct)
 {
  var graph=WorkflowValidation.Parse(version.GraphJson);var schedule=await db.Set<WorkflowSchedule>().SingleOrDefaultAsync(x=>x.DefinitionId==definition.Id,ct);
  if(graph.Trigger!="scheduled"){if(schedule!=null)schedule.IsEnabled=false;return;}if(schedule==null){schedule=new(){TenantId=definition.TenantId,DefinitionId=definition.Id};db.Add(schedule);}schedule.WorkflowVersionId=version.Id;schedule.ActorId=version.PublishedBy;schedule.ActivatedAtUtc=DateTime.UtcNow;schedule.NextAtUtc=WorkflowTriggers.Next(graph.Schedule!,DateTime.UtcNow);schedule.IsEnabled=true;schedule.LastError="";schedule.LeaseUntilUtc=null;
 }
 private static object Connector(WorkflowConnector x)=>new{x.Id,x.Name,x.Kind,x.Endpoint,x.Port,x.Username,x.Sender,x.Model,x.IsActive,x.Version,hasSecret=x.ProtectedSecret!=""};
 private static void ApplyConnector(WorkflowConnector row,ConnectorSave r,WorkflowConnections connection)
 {
  row.Name=Text(r.Name,160);Choice(r.Kind,"http","smtp","ai");if(r.Kind!="smtp")WorkflowConnections.Endpoint(r.Endpoint);else{Check(Uri.CheckHostName(r.Endpoint)!=UriHostNameType.Unknown&&!r.Endpoint.Contains('/')&&r.Port is >0 and <=65535,"Choose a valid SMTP host and port.");try{_ = new System.Net.Mail.MailAddress(r.Sender);}catch{throw new ValidationException("Enter a valid sender email.");}}
  row.Kind=r.Kind;row.Endpoint=Text(r.Endpoint,2000);row.Port=r.Port;row.Username=r.Username??"";row.Sender=r.Sender??"";row.Model=r.Model??"";row.IsActive=r.IsActive;if(r.Secret!=null){Check(r.Secret.Length<=8000,"Connector secret is too long.");row.ProtectedSecret=string.IsNullOrEmpty(r.Secret)?"":connection.Protect(r.Secret);}
 }
 private static void MapAdvanced(RouteGroupBuilder api,IEndpointRouteBuilder routes)
 {
  MapOperations(api);
  MapCatalogue(api);
  api.MapGet("/directory",(IIdentityDirectory directory,CancellationToken ct)=>directory.GetAsync(ct));
  api.MapGet("/published-versions",async(WorkflowDbContext db,WorkflowExpressions expressions,HttpContext http,CancellationToken ct)=>{var versions=await db.Set<WorkflowVersion>().AsNoTracking().OrderByDescending(x=>x.CreatedAtUtc).Take(1000).ToArrayAsync(ct);var names=await db.Set<WorkflowDefinition>().AsNoTracking().Where(x=>!x.IsArchived).ToDictionaryAsync(x=>x.Id,x=>x.Name,ct);return versions.Where(v=>names.ContainsKey(v.DefinitionId)&&Permissions(http).Contains(expressions.Metadata(WorkflowValidation.Parse(v.GraphJson).EntityKey)?.Permission??"unavailable")).Select(v=>new{v.Id,v.Number,name=names[v.DefinitionId]});});
  api.MapGet("/connectors",async(WorkflowDbContext db,CancellationToken ct)=>(await db.Set<WorkflowConnector>().OrderBy(x=>x.Name).ToListAsync(ct)).Select(Connector)).RequireAuthorization("workflows.integrations");
  api.MapPost("/connectors",async(ConnectorSave r,WorkflowDbContext db,WorkflowConnections connection,IRequestIdentity who,CancellationToken ct)=>{var row=new WorkflowConnector{TenantId=who.TenantId!.Value};ApplyConnector(row,r,connection);db.Add(row);await db.SaveChangesAsync(ct);return Results.Ok(Connector(row));}).RequireAuthorization("workflows.integrations");
  api.MapPut("/connectors/{id:guid}",async(Guid id,ConnectorSave r,WorkflowDbContext db,WorkflowConnections connection,CancellationToken ct)=>{var row=await db.Set<WorkflowConnector>().SingleOrDefaultAsync(x=>x.Id==id,ct)??throw new KeyNotFoundException();if(row.Version!=r.Version)return Conflict();ApplyConnector(row,r,connection);await db.SaveChangesAsync(ct);return Results.Ok(Connector(row));}).RequireAuthorization("workflows.integrations");
  api.MapDelete("/connectors/{id:guid}",async(Guid id,WorkflowDbContext db,CancellationToken ct)=>{var row=await db.Set<WorkflowConnector>().SingleOrDefaultAsync(x=>x.Id==id,ct)??throw new KeyNotFoundException();Check(!await db.Set<WorkflowDelivery>().AnyAsync(x=>x.ConnectorId==id,ct),"This connector has delivery history. Disable it instead.");db.Remove(row);await db.SaveChangesAsync(ct);return Results.NoContent();}).RequireAuthorization("workflows.integrations");
  api.MapGet("/email-templates",async(WorkflowDbContext db,CancellationToken ct)=>await db.Set<WorkflowEmailTemplate>().OrderBy(x=>x.Name).ToListAsync(ct)).RequireAuthorization("workflows.integrations");
  api.MapPost("/email-templates",async(TemplateSave r,WorkflowDbContext db,IRequestIdentity who,CancellationToken ct)=>{var row=new WorkflowEmailTemplate{TenantId=who.TenantId!.Value,Name=Text(r.Name),Subject=Text(r.Subject),Body=Text(r.Body,16000)};WorkflowExpressions.CheckExpression(row.Subject);WorkflowExpressions.CheckExpression(row.Body);db.Add(row);await db.SaveChangesAsync(ct);return Results.Ok(row);}).RequireAuthorization("workflows.integrations");
  api.MapPut("/email-templates/{id:guid}",async(Guid id,TemplateSave r,WorkflowDbContext db,CancellationToken ct)=>{var row=await db.Set<WorkflowEmailTemplate>().SingleOrDefaultAsync(x=>x.Id==id,ct)??throw new KeyNotFoundException();if(row.Version!=r.Version)return Conflict();row.Name=Text(r.Name);row.Subject=Text(r.Subject);row.Body=Text(r.Body,16000);WorkflowExpressions.CheckExpression(row.Subject);WorkflowExpressions.CheckExpression(row.Body);await db.SaveChangesAsync(ct);return Results.Ok(row);}).RequireAuthorization("workflows.integrations");
  api.MapDelete("/email-templates/{id:guid}",async(Guid id,WorkflowDbContext db,CancellationToken ct)=>{var row=await db.Set<WorkflowEmailTemplate>().SingleOrDefaultAsync(x=>x.Id==id,ct)??throw new KeyNotFoundException();db.Remove(row);await db.SaveChangesAsync(ct);return Results.NoContent();}).RequireAuthorization("workflows.integrations");
  api.MapGet("/deliveries",async(WorkflowDbContext db,CancellationToken ct)=>await db.Set<WorkflowDelivery>().OrderByDescending(x=>x.CreatedAtUtc).Take(100).Select(x=>new{x.Id,x.RunId,x.ConnectorId,x.Kind,x.Status,x.Error,x.StartedAtUtc,x.FinishedAtUtc,x.Version}).ToListAsync(ct)).RequireAuthorization("workflows.integrations");
  api.MapPost("/deliveries/{id:guid}/reconcile",async(Guid id,DeliveryReconcile r,WorkflowDbContext db,CancellationToken ct)=>{var row=await db.Set<WorkflowDelivery>().SingleOrDefaultAsync(x=>x.Id==id,ct)??throw new KeyNotFoundException();if(row.Version!=r.Version)return Conflict();Check(row.Status is "unknown" or "sending","Only uncertain deliveries can be reconciled.");Check(r.ConfirmedNotDelivered,"Confirm with the provider that it did not receive this delivery before retrying.");var run=await db.Set<WorkflowRun>().SingleAsync(x=>x.Id==row.RunId,ct);Check(run.Status=="failed","Stop or wait for the run before reconciling delivery.");db.Add(new WorkflowStep{TenantId=row.TenantId,RunId=row.RunId,NodeId=run.CurrentNodeId,Kind="control",Sequence=++run.Steps,Outcome="Provider non-delivery confirmed; explicit replay authorized"});row.Status="ready";row.Error="";row.StartedAtUtc=null;row.FinishedAtUtc=null;await db.SaveChangesAsync(ct);return Results.NoContent();}).RequireAuthorization("workflows.integrations");
  api.MapGet("/schedules",async(WorkflowDbContext db,CancellationToken ct)=>await db.Set<WorkflowSchedule>().ToListAsync(ct));
  api.MapGet("/definitions/{id:guid}/export",async(Guid id,WorkflowDbContext db,IEnumerable<Nexora.BuildingBlocks.Reporting.IReportDataset> datasets,HttpContext http,CancellationToken ct)=>{var row=await Definition(id,db,datasets,http,ct);return new{schema="nexora.workflow/2",row.Name,row.Description,graph=WorkflowValidation.Parse(row.DraftJson)};});
  api.MapPost("/import",async(WorkflowSave r,WorkflowDbContext db,WorkflowValidation validation,WorkflowExpressions expressions,IRequestIdentity who,HttpContext http,CancellationToken ct)=>{var errors=WorkflowValidation.Structure(r.Graph);Check(errors.Length==0,string.Join(" ",errors));expressions.Source(r.Graph.EntityKey,Permissions(http));var row=new WorkflowDefinition{TenantId=who.TenantId!.Value,Name=Text(r.Name),Description=r.Description??"",DraftJson=WorkflowValidation.Serialize(r.Graph)};db.Add(row);Audit(db,who,row.Id,"draft.imported");await db.SaveChangesAsync(ct);return Results.Ok(row);}).RequireAuthorization("workflows.create");
  api.MapPost("/definitions/{id:guid}/bulk-execute",async(Guid id,WorkflowBulkStart r,WorkflowDbContext db,IEnumerable<Nexora.BuildingBlocks.Reporting.IReportDataset> datasets,WorkflowExpressions expressions,WorkflowValidation validation,IRequestIdentity who,HttpContext http,CancellationToken ct)=>{var definition=await Definition(id,db,datasets,http,ct);Check(definition.ActiveVersionId!=null,"Activate a published version first.");Check(r.RecordIds is {Length:>0 and <=100},"Select 1–100 records.");var version=await db.Set<WorkflowVersion>().SingleAsync(x=>x.Id==definition.ActiveVersionId,ct);var graph=WorkflowValidation.Parse(version.GraphJson);var errors=await validation.ValidateAsync(graph,Permissions(http),ct);Check(errors.Length==0,string.Join(" ",errors));var result=new List<WorkflowRun>();foreach(var recordId in r.RecordIds.Distinct()){var record=await expressions.Source(graph.EntityKey,Permissions(http)).FindAsync(recordId,ct)??throw new ValidationException("A selected record is unavailable.");result.Add(await WorkflowTriggers.EnqueueAsync(db,version,who.UserId!.Value,recordId,record.Label,"bulk:"+WorkflowProcessor.ActionId(recordId,Text(r.RequestKey,80)),ct:ct));}await db.SaveChangesAsync(ct);return Results.Accepted(value:result);}).RequireAuthorization("workflows.execute");
  api.MapPost("/test",async(WorkflowTest r,WorkflowPreview preview,HttpContext http,CancellationToken ct)=>await preview.TestAsync(r,Permissions(http),ct)).RequireAuthorization("workflows.execute");
  api.MapGet("/templates",(IRequestIdentity who)=>WorkflowTemplates.All.Concat(WorkflowOperationsTemplates.All(who.UserId!.Value).Cast<object>()));
  api.MapPost("/templates/{key}/draft",async(string key,WorkflowTemplateOptions options,IRequestIdentity who,IIdentityDirectory directory,WorkflowDbContext db,WorkflowExpressions expressions,HttpContext http,CancellationToken ct)=>{
   Check(options.ReminderDays is >=1 and <=365&&options.BeforeExpiryDays is >=0 and <=365&&options.GraceDays is >=0 and <=365,"Choose reminder and renewal periods within 0–365 days (reminder at least one day).");
   Choice(options.RecordKind,"contacts","accounts");Check(options.Values==null||options.Values.Count<=20&&options.Values.All(p=>WorkflowValidation.VariableName(p.Key)&&p.Value.Length<=500),"Provide valid bounded template configuration.");
   Check(await directory.IsValidOwnerAsync(options.ReviewerId??who.UserId,null,ct)&&await directory.IsValidOwnerAsync(options.EscalationUserId??options.ReviewerId??who.UserId,null,ct),"Choose active tenant reviewers and escalation users.");
   if(options.EmailConnectorId!=null){Check(Permissions(http).Contains("workflows.integrations"),"Integration permission is required to configure email.");Check(await db.Set<WorkflowConnector>().AnyAsync(x=>x.Id==options.EmailConnectorId&&x.Kind=="smtp"&&x.IsActive,ct),"Choose an approved active SMTP connector.");Check(!string.IsNullOrWhiteSpace(options.Recipient)&&options.Recipient.Length<=500,"Set the member email address or supported recipient expression.");WorkflowExpressions.CheckExpression(options.Recipient);}
   var template=WorkflowOperationsTemplates.Build(key,who.UserId!.Value,options);expressions.Source(template.Graph.EntityKey,Permissions(http));return Results.Ok(template);
  }).RequireAuthorization("workflows.create");
  api.MapPost("/ai-draft",async(AiDraft r,WorkflowConnections connections,IEnumerable<Nexora.BuildingBlocks.Persistence.IWorkflowEntitySource> sources,IEnumerable<IWorkflowActionHandler> handlers,WorkflowValidation validation,HttpContext http,CancellationToken ct)=>{var metadata=new{entities=sources.Where(x=>Permissions(http).Contains(x.Metadata.Permission)).Select(x=>x.Metadata),actions=handlers.Where(x=>x.Descriptor.RequiredPermissions.All(Permissions(http).Contains)).Select(x=>x.Descriptor),triggers=WorkflowValidation.Triggers,nodeKinds=WorkflowValidation.NodeKinds,operators=WorkflowExpressions.Operators};var generated=await connections.GenerateAsync(r.ConnectorId,r.Prompt,metadata,ct);WorkflowSave draft;try{draft=JsonSerializer.Deserialize<WorkflowSave>(generated,WorkflowValidation.Json)??throw new JsonException();}catch{throw new ValidationException("AI returned invalid workflow JSON. No draft was saved.");}var errors=await validation.ValidateAsync(draft.Graph,Permissions(http),ct);return Results.Ok(new{draft,errors,requiresReview=true});}).RequireAuthorization("workflows.ai","workflows.create","workflows.integrations");
  api.MapPost("/definitions/{id:guid}/webhook",async(Guid id,WorkflowDbContext db,IEnumerable<Nexora.BuildingBlocks.Reporting.IReportDataset> datasets,IRequestIdentity who,WorkflowConnections connections,HttpContext http,CancellationToken ct)=>{var definition=await Definition(id,db,datasets,http,ct);var row=await db.Set<WorkflowWebhook>().SingleOrDefaultAsync(x=>x.DefinitionId==id,ct);if(row==null){row=new(){TenantId=definition.TenantId,DefinitionId=id};db.Add(row);}var secret=Convert.ToHexString(RandomNumberGenerator.GetBytes(32));row.ActorId=who.UserId!.Value;row.ProtectedSecret=connections.Protect(secret);row.IsActive=true;Audit(db,who,id,"webhook.rotated");await db.SaveChangesAsync(ct);return Results.Ok(new{row.Id,url="/api/v1/workflow-hooks/"+row.Id,secret,signing="HMAC-SHA256 of timestamp + '.' + raw JSON body; X-Nexora-Timestamp Unix seconds and X-Nexora-Signature hex headers"});}).RequireAuthorization("workflows.integrations","workflows.execute");
  routes.MapPost("/api/v1/workflow-hooks/{id:guid}",async(Guid id,HttpContext http,WorkflowDbContext db,WorkflowConnections connections,IWorkflowPrincipalDirectory directory,WorkflowExecutionContext execution,WorkflowExpressions expressions,WorkflowValidation validation,CancellationToken ct)=>
  {
   if(http.Request.ContentLength>16384||!long.TryParse(http.Request.Headers["X-Nexora-Timestamp"],out var stamp)||Math.Abs(DateTimeOffset.UtcNow.ToUnixTimeSeconds()-stamp)>300)return Results.Unauthorized();var hook=await db.Set<WorkflowWebhook>().IgnoreQueryFilters().AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id&&x.IsActive,ct);if(hook==null)return Results.Unauthorized();using var reader=new StreamReader(http.Request.Body,Encoding.UTF8);var buffer=new char[16385];var count=await reader.ReadBlockAsync(buffer.AsMemory(),ct);if(count>16384)return Results.BadRequest();var raw=new string(buffer,0,count);byte[] signature;try{signature=Convert.FromHexString(http.Request.Headers["X-Nexora-Signature"].ToString());}catch{return Results.Unauthorized();}var expected=HMACSHA256.HashData(Encoding.UTF8.GetBytes(connections.Unprotect(hook.ProtectedSecret)),Encoding.UTF8.GetBytes(stamp+"."+raw));if(!CryptographicOperations.FixedTimeEquals(signature,expected))return Results.Unauthorized();var principal=await directory.ResolveAsync(hook.TenantId,hook.ActorId,ct);if(principal==null||!principal.Permissions.Contains("workflows.execute"))return Results.Unauthorized();using var identity=execution.Enter(principal);
   try{var start=JsonSerializer.Deserialize<WorkflowStart>(raw,WorkflowValidation.Json)??throw new JsonException();var definition=await db.Set<WorkflowDefinition>().SingleAsync(x=>x.Id==hook.DefinitionId&&!x.IsArchived,ct);if(definition.ActiveVersionId==null)return Results.Conflict();var version=await db.Set<WorkflowVersion>().SingleAsync(x=>x.Id==definition.ActiveVersionId,ct);var graph=WorkflowValidation.Parse(version.GraphJson);if(graph.Trigger!="external")return Results.Conflict();var errors=await validation.ValidateAsync(graph,principal.Permissions,ct);if(errors.Length>0)return Results.Forbid();var record=await expressions.Source(graph.EntityKey,principal.Permissions).FindAsync(start.RecordId,ct);if(record==null)return Results.NotFound();var run=await WorkflowTriggers.EnqueueAsync(db,version,principal.UserId,record.Id,record.Label,"hook:"+WorkflowProcessor.ActionId(hook.Id,Text(start.RequestKey,80)),new JsonObject{["kind"]="external"}.ToJsonString(),context:JsonSerializer.Serialize(new{variables=start.Variables??new()}),ct:ct);await db.SaveChangesAsync(ct);return Results.Accepted(value:new{run.Id,run.Status});}catch(JsonException){return Results.BadRequest();}catch(ValidationException ex){return Results.Problem(statusCode:400,title:ex.Message);}
  }).AllowAnonymous().RequireRateLimiting("workflow-hooks");
 }
